B.bkM=s(["\u041f\u0440\u0438\u043b\u0430\u0433\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u2014 \u044d\u0442\u043e \u043f\u0430\u043b\u0438\u0442\u0440\u0430 \u0445\u0443\u0434\u043e\u0436\u043d\u0438\u043a\u0430 \u0441 \u044f\u0440\u043a\u0438\u043c\u0438 \u043a\u0440\u0430\u0441\u043a\u0430\u043c\u0438, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u0440\u0430\u0441\u043a\u0440\u0430\u0448\u0438\u0432\u0430\u0435\u0442 \u0447\u0435\u0440\u043d\u043e-\u0431\u0435\u043b\u044b\u0439 \u043c\u0438\u0440 \u043f\u0440\u0435\u0434\u043c\u0435\u0442\u043e\u0432.","\u041f\u0440\u0438\u043b\u0430\u0433\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u2014 \u0432\u0435\u0440\u043d\u044b\u0439 \u043e\u0440\u0443\u0436\u0435\u043d\u043e\u0441\u0435\u0446 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0433\u043e: \u043a\u0443\u0434\u0430 \u0440\u044b\u0446\u0430\u0440\u044c-\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435, \u0442\u0443\u0434\u0430 \u0438 \u043e\u0440\u0443\u0436\u0435\u043d\u043e\u0441\u0435\u0446 \u0432 \u0442\u0435\u0445 \u0436\u0435 \u0434\u043e\u0441\u043f\u0435\u0445\u0430\u0445 (\u0440\u043e\u0434\u0435 \u0438 \u0447\u0438\u0441\u043b\u0435)."],t.s)
B.bbp=s(["\u041f\u0440\u0438\u043b\u0430\u0433\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435 (\u041a\u0430\u043a\u043e\u0439? \u041a\u0430\u043a\u0430\u044f? \u041a\u0430\u043a\u043e\u0435?)","\u0421\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435 (\u043f\u0440\u0435\u0434\u043c\u0435\u0442)"],t.s)
