B.bUq=new A.dx("\u0417\u0432\u0443\u043a\u0438 \u2014 \u044d\u0442\u043e \u0437\u0432\u0443\u0447\u0430\u0449\u0430\u044f \u043c\u0430\u0442\u0435\u0440\u0438\u044f \u044f\u0437\u044b\u043a\u0430, \u0442\u043e, \u0447\u0442\u043e \u043c\u044b \u043f\u0440\u043e\u0438\u0437\u043d\u043e\u0441\u0438\u043c \u0438 \u0441\u043b\u044b\u0448\u0438\u043c \u0443\u0445\u043e\u043c. \u0411\u0443\u043a\u0432\u044b \u2014 \u044d\u0442\u043e \u0433\u0440\u0430\u0444\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0437\u043d\u0430\u0447\u043a\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u043c\u0438 \u0437\u0432\u0443\u043a\u0438 \u0437\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u0432 \u0442\u0435\u0442\u0440\u0430\u0434\u0438 (\u043c\u044b \u0438\u0445 \u0432\u0438\u0434\u0438\u043c \u0438 \u043f\u0438\u0448\u0435\u043c). \u0413\u043b\u0430\u0441\u043d\u044b\u0435 \u0437\u0432\u0443\u043a\u0438 \u043f\u043e\u044e\u0442\u0441\u044f \u0447\u0438\u0441\u0442\u044b\u043c \u0433\u043e\u043b\u043e\u0441\u043e\u043c, \u0432\u044b\u0434\u044b\u0445\u0430\u0435\u043c\u044b\u0439 \u0432\u043e\u0437\u0434\u0443\u0445 \u043d\u0435 \u0432\u0441\u0442\u0440\u0435\u0447\u0430\u0435\u0442 \u0432\u043e \u0440\u0442\u0443 \u043d\u0438\u043a\u0430\u043a\u0438\u0445 \u043f\u0440\u0435\u0433\u0440\u0430\u0434 [\u0430, \u043e, \u0443, \u044b, \u0438, \u044d]. \u0421\u043e\u0433\u043b\u0430\u0441\u043d\u044b\u0435 \u0437\u0432\u0443\u043a\u0438 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u043f\u0440\u0435\u043e\u0434\u043e\u043b\u0435\u0432\u0430\u044e\u0442 \u043f\u0440\u0435\u0433\u0440\u0430\u0434\u0443 \u2014 \u0441\u043c\u044b\u043a\u0430\u043d\u0438\u0435 \u0433\u0443\u0431, \u0437\u0443\u0431\u043e\u0432 \u0438\u043b\u0438 \u043f\u0440\u0438\u0436\u0430\u0442\u0438\u0435 \u044f\u0437\u044b\u0447\u043a\u0430 [\u0431, \u043f, \u043c, \u0441, \u043a]. \u0418\u043c\u0435\u043d\u043d\u043e \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0433\u043b\u0430\u0441\u043d\u044b\u0435 \u0442\u044f\u043d\u0443\u0442\u0441\u044f, \u043a\u0430\u043a \u043f\u0435\u0441\u043d\u044f, \u0430 \u0441\u043e\u0433\u043b\u0430\u0441\u043d\u044b\u0435 \u0448\u0443\u0440\u0448\u0430\u0442, \u0441\u0432\u0438\u0441\u0442\u044f\u0442 \u0438\u043b\u0438 \u0441\u0442\u0443\u0447\u0430\u0442.",B.bl8,"\u0414\u0435\u0442\u0438 \u0447\u0430\u0441\u0442\u043e \u043d\u0430\u0437\u044b\u0432\u0430\u044e\u0442 \u0431\u0443\u043a\u0432\u0443 \xab\u041c\xbb \u043a\u0430\u043a [\u044d\u043c], \u0430 \u0431\u0443\u043a\u0432\u0443 \xab\u041a\xbb \u043a\u0430\u043a [\u043a\u0430], \u0438\u0437-\u0437\u0430 \u0447\u0435\u0433\u043e \u0447\u0438\u0442\u0430\u044e\u0442 \u0441\u043b\u043e\u0432\u043e \xab\u041c\u0410\u041c\u0410\xbb \u043a\u0430\u043a \xab\u042d\u041c\u0410\u042d\u041c\u0410\xbb. \u041b\u043e\u0432\u0443\u0448\u043a\u0430: \u0431\u0443\u043a\u0432\u0430 \u0438\u043c\u0435\u0435\u0442 \u043d\u0430\u0437\u0432\u0430\u043d\u0438\u0435 (\xab\u044d\u043c\xbb), \u043d\u043e \u043f\u0440\u043e\u0438\u0437\u043d\u043e\u0441\u0438\u0442\u044c \u043c\u044b \u0434\u043e\u043b\u0436\u043d\u044b \u0447\u0438\u0441\u0442\u044b\u0439 \u043a\u043e\u0440\u043e\u0442\u043a\u0438\u0439 \u0437\u0432\u0443\u043a [\u043c]. \u0411\u0443\u043a\u0432\u044b \u0415, \u0401, \u042e, \u042f \u2014 \u044d\u0442\u043e \u0431\u0443\u043a\u0432\u044b, \u0430 \u043d\u0435 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0435 \u0447\u0438\u0441\u0442\u044b\u0435 \u0437\u0432\u0443\u043a\u0438.","\u0412\u043e\u0437\u0434\u0443\u0445 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e \u0442\u0435\u0447\u0451\u0442 \u2014 \u0433\u043b\u0430\u0441\u043d\u044b\u0439 \u0437\u0432\u0443\u043a \u043f\u043e\u0451\u0442! \u041f\u0440\u0435\u0433\u0440\u0430\u0434\u0430 \u043d\u0430 \u043f\u0443\u0442\u0438 \u2014 \u0441\u043e\u0433\u043b\u0430\u0441\u043d\u044b\u0439 \u0437\u0432\u0443\u043a \u0438\u0449\u0438! \u0421\u043a\u043e\u043b\u044c\u043a\u043e \u0432 \u0441\u043b\u043e\u0432\u0435 \u0433\u043b\u0430\u0441\u043d\u044b\u0445 \u2014 \u0441\u0442\u043e\u043b\u044c\u043a\u043e \u0438 \u0441\u043b\u043e\u0433\u043e\u0432!",'\u0423\u0447\u0438\u0442\u0435\u043b\u044c: "\u0420\u0435\u0431\u044f\u0442\u0430, \u043f\u043e\u043b\u043e\u0436\u0438\u0442\u0435 \u043b\u0430\u0434\u043e\u0448\u043a\u0443 \u043d\u0430 \u0433\u043e\u0440\u043b\u044b\u0448\u043a\u043e \u0438 \u0448\u0438\u0440\u043e\u043a\u043e \u043e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u0440\u043e\u0442: [\u0430-\u0430-\u0430]. \u0427\u0442\u043e \u0447\u0443\u0432\u0441\u0442\u0432\u0443\u0435\u0442 \u043b\u0430\u0434\u043e\u0448\u043a\u0430? \u0427\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 \u044f\u0437\u044b\u0447\u043e\u043a?"\n\u0414\u0435\u0442\u0438: "\u0413\u043e\u0440\u043b\u044b\u0448\u043a\u043e \u0434\u0440\u043e\u0436\u0438\u0442, \u043f\u043e\u0451\u0442! \u0410 \u0440\u043e\u0442 \u043e\u0442\u043a\u0440\u044b\u0442, \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043c\u0435\u0448\u0430\u0435\u0442!"\n\u0423\u0447\u0438\u0442\u0435\u043b\u044c: "\u0412\u0435\u0440\u043d\u043e, \u044d\u0442\u043e \u0433\u043b\u0430\u0441\u043d\u044b\u0439 \u0437\u0432\u0443\u043a \u2014 \u0433\u043e\u043b\u043e\u0441 \u043b\u044c\u0451\u0442\u0441\u044f \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e! \u0410 \u0442\u0435\u043f\u0435\u0440\u044c \u0441\u043e\u043c\u043a\u043d\u0438\u0442\u0435 \u0433\u0443\u0431\u044b \u0438 \u043f\u0440\u043e\u0438\u0437\u043d\u0435\u0441\u0438\u0442\u0435: [\u043c-\u043c-\u043c]. \u041f\u043e\u043b\u0443\u0447\u0438\u0442\u0441\u044f \u043b\u0438 \u0441\u043f\u0435\u0442\u044c \u0441 \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u043c \u0440\u0442\u043e\u043c?"\n\u0414\u0435\u0442\u0438: "\u041d\u0435\u0442! \u0413\u0443\u0431\u044b \u0437\u0430\u043a\u0440\u044b\u043b\u0438 \u0432\u043e\u0440\u043e\u0442\u0430 \u0432\u043e\u0437\u0434\u0443\u0445\u0443!"\n\u0423\u0447\u0438\u0442\u0435\u043b\u044c: "\u0412\u043e\u0442 \u043e\u043d\u0430 \u2014 \u043f\u0440\u0435\u0433\u0440\u0430\u0434\u0430! \u0417\u043d\u0430\u0447\u0438\u0442, \u0437\u0432\u0443\u043a [\u043c] \u2014 \u0441\u043e\u0433\u043b\u0430\u0441\u043d\u044b\u0439! \u0417\u0430\u043f\u043e\u043c\u043d\u0438\u0442\u0435 \u043d\u0430\u0448 \u0441\u0435\u043a\u0440\u0435\u0442..."',B.bmc,B.bE7,'\u041d\u0435\u0437\u043d\u0430\u0439\u043a\u0430 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442: "\u0417\u0432\u0443\u043a [\u043c] \u2014 \u0433\u043b\u0430\u0441\u043d\u044b\u0439, \u043f\u043e\u0442\u043e\u043c\u0443 \u0447\u0442\u043e \u043a\u043e\u0440\u043e\u0432\u0430 \u0433\u043e\u0432\u043e\u0440\u0438\u0442 \u041c\u0443-\u0443-\u0443, \u0437\u043d\u0430\u0447\u0438\u0442 \u043e\u043d \u043f\u043e\u0451\u0442\u0441\u044f!"',B.bMG,"1 - 2 - 3 - 4","\u0410\u0418\u0421\u0422","\u041d\u0430\u0439\u0434\u0438 \u0441\u043b\u043e\u0432\u043e \u0438\u0437 \u0442\u0440\u0451\u0445 \u0431\u0443\u043a\u0432, \u0432 \u043a\u043e\u0442\u043e\u0440\u043e\u043c \u0440\u043e\u0432\u043d\u043e \u043e\u0434\u0438\u043d \u0433\u043b\u0430\u0441\u043d\u044b\u0439 \u0437\u0432\u0443\u043a \u0441\u0442\u043e\u0438\u0442 \u043f\u043e\u0441\u0435\u0440\u0435\u0434\u0438\u043d\u0435 \u043c\u0435\u0436\u0434\u0443 \u0434\u0432\u0443\u043c\u044f \u0442\u0432\u0451\u0440\u0434\u044b\u043c\u0438 \u0441\u043e\u0433\u043b\u0430\u0441\u043d\u044b\u043c\u0438 \u0437\u0432\u0443\u043a\u0430\u043c\u0438.",B.bpr,"\u0434\u043e\u043c (\u0441\u043e\u0433\u043b\u0430\u0441\u043d\u044b\u0439 [\u0434] - \u0433\u043b\u0430\u0441\u043d\u044b\u0439 [\u043e] - \u0441\u043e\u0433\u043b\u0430\u0441\u043d\u044b\u0439 [\u043c])","\u042d\u043b\u0435\u043c\u0435\u043d\u0442\u044b: \u043d\u0430\u043a\u043b\u043e\u043d\u043d\u0430\u044f \u043b\u0438\u043d\u0438\u044f \u0441 \u0437\u0430\u043a\u0440\u0443\u0433\u043b\u0435\u043d\u0438\u0435\u043c \u0432\u043d\u0438\u0437\u0443 \u0432\u043f\u0440\u0430\u0432\u043e (\xab\u043a\u0440\u044e\u0447\u043e\u043a\xbb), \u043f\u043b\u0430\u0432\u043d\u044b\u0439 \u043e\u0432\u0430\u043b \u0431\u0443\u043a\u0432 \u043e, \u0430.","1. \u041e\u0431\u0440\u0430\u0437\u0435\u0446: \u043e \u2014 \u0433\u043b\u0430\u0441\u043d\u044b\u0439, \u043f \u2014 \u0441\u043e\u0433\u043b\u0430\u0441\u043d\u044b\u0439; \u0443 \u2014 \u0433\u043b\u0430\u0441\u043d\u044b\u0439, \u0440 \u2014 \u0441\u043e\u0433\u043b\u0430\u0441\u043d\u044b\u0439; \u044d \u2014 \u0433\u043b\u0430\u0441\u043d\u044b\u0439, \u0441 \u2014 \u0441\u043e\u0433\u043b\u0430\u0441\u043d\u044b\u0439. 2. \u0421\u0442\u0440\u0435\u043b\u043a\u0438: [\u0430]->\u0413\u043b\u0430\u0441\u043d\u044b\u0439, [\u043c]->\u0421\u043e\u0433\u043b\u0430\u0441\u043d\u044b\u0439 \u0442\u0432\u0451\u0440\u0434\u044b\u0439, [\u0443]->\u0413\u043b\u0430\u0441\u043d\u044b\u0439, [\u043a']->\u0421\u043e\u0433\u043b\u0430\u0441\u043d\u044b\u0439 \u043c\u044f\u0433\u043a\u0438\u0439. 3. \u0420\u0430\u0441\u043a\u0440\u0430\u0441\u043a\u0430: \u0410,\u0423,\u041e,\u042b,\u0418 \u2014 \u043a\u0440\u0430\u0441\u043d\u044b\u0435; \u0411,\u041c,\u041a,\u0414,\u0422 \u2014 \u0441\u0438\u043d\u0438\u0435. 4. \u0422\u0430\u0431\u043b\u0438\u0446\u0430: \u0413\u043b\u0430\u0441\u043d\u044b\u0435: [\u0430], [\u043e], [\u0443], [\u0438]; \u0421\u043e\u0433\u043b\u0430\u0441\u043d\u044b\u0435: [\u0431], [\u043a], [\u0441], [\u0442]. 5. \u041e\u0448\u0438\u0431\u043a\u0430 \u041d\u0435\u0437\u043d\u0430\u0439\u043a\u0438: \u0433\u0443\u0431\u044b \u0441\u043e\u043c\u043a\u043d\u0443\u0442\u044b, \u0441\u043e\u0437\u0434\u0430\u044e\u0442 \u043f\u0440\u0435\u0433\u0440\u0430\u0434\u0443. 7. \u0428\u0438\u0444\u0440: \u0410\u0418\u0421\u0422. 8. \u0422\u0420\u0418\u0417: \u0441\u043b\u043e\u0432\u043e \u0414\u041e\u041c.")
B.bE8=s(["\u041a\u043e\u0440\u0435\u043d\u044c \u0441\u043b\u043e\u0432\u0430 \u2014 \u043a\u0430\u043a \u043a\u043e\u0440\u0435\u043d\u044c \u043c\u043e\u0433\u0443\u0447\u0435\u0433\u043e \u0434\u0443\u0431\u0430: \u0438\u0437 \u043e\u0434\u043d\u043e\u0433\u043e \u043a\u043e\u0440\u043d\u044f \u0432\u044b\u0440\u0430\u0441\u0442\u0430\u044e\u0442 \u043a\u0440\u0435\u043f\u043a\u0438\u0435 \u0432\u0435\u0442\u0432\u0438 \u2014 \u0441\u043b\u043e\u0432\u0430-\u0431\u0440\u0430\u0442\u044c\u044f.","\u0421\u0435\u043c\u044c\u044f \u0441\u043b\u043e\u0432 \u2014 \u043a\u0430\u043a \u0441\u0435\u043c\u044c\u044f \u043b\u044e\u0434\u0435\u0439: \u0443 \u0432\u0441\u0435\u0445 \u043e\u0434\u043d\u0430 \u0444\u0430\u043c\u0438\u043b\u0438\u044f (\u043a\u043e\u0440\u0435\u043d\u044c) \u0438 \u043e\u0431\u0449\u0435\u0435 \u0441\u0435\u043c\u0435\u0439\u043d\u043e\u0435 \u0434\u0435\u043b\u043e (\u0441\u043c\u044b\u0441\u043b)."],t.s)
B.b1C=s(["\u0421\u0435\u043c\u044c\u044f \u0441\u043b\u043e\u0432\u0430 \u0412\u041e\u0414\u0410","\u0421\u0435\u043c\u044c\u044f \u0441\u043b\u043e\u0432\u0430 \u041b\u0415\u0421","\u0421\u0435\u043c\u044c\u044f \u0441\u043b\u043e\u0432\u0430 \u0414\u041e\u041c"],t.s)
B.bjU=s(["\u0432\u043e\u0434\u043d\u044b\u0439","\u043b\u0435\u0441\u043d\u043e\u0439","\u0434\u043e\u043c\u0438\u043a","\u0432\u043e\u0434\u0438\u0447\u043a\u0430","\u043b\u0435\u0441\u043d\u0438\u043a","\u0434\u043e\u043c\u043e\u0432\u043e\u0439","\u043f\u043e\u0434\u0432\u043e\u0434\u043d\u0438\u043a","\u043b\u0435\u0441\u043e\u0447\u0435\u043a"],t.s)
B.bOT=new A.ai(B.e2,["\u0421","\u0410","\u0414","\u0418","\u041a"],t.w)
